diff --git a/infra/dumps.tf b/infra/dumps.tf
new file mode 100644
index 0000000..112d549
--- /dev/null
+++ b/infra/dumps.tf
@@ -0,0 +1,60 @@
+# Rollout: review the plan for additions only, apply all bucket controls, and
+# stop on any failure before enabling the nightly uploader.
+# Rollback: stop uploads and retain this bucket and its security resources.
+# To stop expiration, set the lifecycle rule status to Disabled and apply.
+# Do not revert by removing this file: prevent_destroy does not protect a
+# resource once its configuration is removed. Expired dumps cannot be recovered.
+resource "aws_s3_bucket" "dumps" {
+  bucket        = "shop-db-dumps-${var.env}"
+  force_destroy = false
+
+  lifecycle {
+    prevent_destroy = true
+  }
+}
+
+resource "aws_s3_bucket_public_access_block" "dumps" {
+  bucket = aws_s3_bucket.dumps.id
+
+  block_public_acls       = true
+  block_public_policy     = true
+  ignore_public_acls      = true
+  restrict_public_buckets = true
+}
+
+resource "aws_s3_bucket_ownership_controls" "dumps" {
+  bucket = aws_s3_bucket.dumps.id
+
+  rule {
+    object_ownership = "BucketOwnerEnforced"
+  }
+}
+
+resource "aws_s3_bucket_server_side_encryption_configuration" "dumps" {
+  bucket = aws_s3_bucket.dumps.id
+
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm = "AES256"
+    }
+  }
+}
+
+resource "aws_s3_bucket_lifecycle_configuration" "dumps" {
+  bucket = aws_s3_bucket.dumps.id
+
+  rule {
+    id     = "expire-nightly-dumps"
